#!/usr/bin/env bash
#
# Regenerate languages/aisooq-connector.pot — the template translators work from.
#
# Run this whenever you add, change or delete a translatable string:
#
#   bin/make-pot.sh          # or: composer i18n
#
# ONE wp-cli version, everywhere. 2.11 and 2.12 emit different bodies for this
# plugin (2.12 adds `#, php-format` flags), so a template generated by one and
# checked by the other differs by ~90 lines with no string change behind it.
# Bumping this pin means regenerating and committing the .pot in the same commit.
WP_CLI_VERSION="${WP_CLI_VERSION:-2.12.0}"

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

# `--no-location` on purpose. With file:line references, 544 of the template's
# lines are `#:` comments and ANY edit that shifts a line in includes/ rewrites
# hundreds of them — the template would go stale on commits that change no
# string at all. Translators lose the file:line context; in exchange the file
# only moves when the strings do.
#
# `--exclude` MERGES with wp-cli's built-in list (node_modules, vendor, tests,
# .*, *.min.js are already excluded), so only dist and bin need naming here.
ARGS=(
	i18n make-pot . languages/aisooq-connector.pot
	--slug=aisooq-connector
	--exclude=dist,bin
	--no-location
	'--headers={"Report-Msgid-Bugs-To":"https://github.com/allvee/aisooq-wp-connector/issues","Language-Team":"AI Sooq <https://github.com/allvee/aisooq-wp-connector>","POT-Creation-Date":"","X-Generator":""}'
)

# POT-Creation-Date and X-Generator are blanked above rather than left to
# wp-cli: both change on every run, which would make the committed template
# differ from a fresh one for no reason and defeat the staleness test.

if command -v wp >/dev/null 2>&1; then
	wp "${ARGS[@]}"
elif command -v docker >/dev/null 2>&1; then
	docker run --rm -v "$ROOT":/app -w /app "wordpress:cli-${WP_CLI_VERSION}-php8.2" wp "${ARGS[@]}"
else
	echo "error: need either wp-cli on PATH or docker to regenerate the template" >&2
	exit 1
fi

echo "regenerated: languages/aisooq-connector.pot ($(grep -c '^msgid "' languages/aisooq-connector.pot || true) strings)"
